export const IN_CITIES_2 = [
  // Uttar Pradesh
  { s: "agra", n: "Agra", p: "uttar-pradesh", ll: [27.18, 78.01], t: "heritage honeymoon family", d: "Agra was the Mughal capital for much of the sixteenth and seventeenth centuries, and it holds three UNESCO sites: the Taj Mahal, Agra Fort and nearby Fatehpur Sikri. The Taj, built by Shah Jahan for Mumtaz Mahal, changes colour from dawn to dusk.", a: [["Taj Mahal", "White marble mausoleum (closed Fridays)"], ["Agra Fort", "Red sandstone fort and palaces"], ["Fatehpur Sikri", "Akbar's abandoned capital, 40 km away"], ["Itimad-ud-Daulah", "The 'Baby Taj' with inlaid marble"], ["Mehtab Bagh", "Garden across the river with sunset views of the Taj"], ["Akbar's Tomb, Sikandra", "Mausoleum of the great emperor"]], ac: ["Sunrise at the Taj", "Marble inlay workshop visit", "Sunset at Mehtab Bagh", "Mughal cuisine dinner"], f: ["Agra petha", "Bedai and jalebi breakfast", "Mughlai curries"], bt: ["October to March", "Pleasant days; winter mornings can be foggy, which gives the Taj a soft, misty look."], r: ["Agra Airport (AGR), with limited flights; Delhi (DEL), about 230 km", "Agra Cantt station, with the Gatimaan and Shatabdi from Delhi", "About 3.5 hours from Delhi via the Yamuna Expressway"], days: "1–2", tip: "Enter the Taj at sunrise through the East Gate; it is the least crowded and the light is beautiful.", b: "First-time visitors, couples, families" },
  { s: "varanasi", n: "Varanasi", p: "uttar-pradesh", ll: [25.32, 83.01], t: "pilgrimage heritage culture", d: "Varanasi is one of the oldest living cities in the world and the holiest place in Hinduism. Life, prayer and death happen side by side on its ghats along the Ganga, and the evening Ganga aarti at Dashashwamedh Ghat is unforgettable.", a: [["Dashashwamedh Ghat", "Main ghat and site of the evening Ganga aarti"], ["Kashi Vishwanath Temple and corridor", "Golden-spired Shiva temple"], ["Manikarnika Ghat", "The principal cremation ghat"], ["Sarnath", "Where the Buddha gave his first sermon, 10 km away"], ["Assi Ghat", "Morning aarti and music"], ["Ramnagar Fort", "Riverside fort of the Maharaja of Benares"]], ac: ["Sunrise boat ride", "Evening Ganga aarti", "Old city lane walk", "Banarasi silk weaving visit", "Classical music concert"], f: ["Kachori sabzi", "Banarasi paan", "Malaiyyo (winter)", "Lassi in clay cups"], bt: ["October to March", "Dev Deepawali (November) lights up every ghat with lamps."], r: ["Lal Bahadur Shastri International Airport (VNS), about 25 km", "Varanasi Junction and Banaras stations", "About 5 hours from Prayagraj or Ayodhya region by road"], days: "2", tip: "Take the dawn boat on your first morning; the ghats are at their most atmospheric then.", b: "Spiritual travellers, photographers, culture lovers" },
  { s: "mathura-vrindavan", n: "Mathura & Vrindavan", p: "uttar-pradesh", ll: [27.49, 77.67], t: "pilgrimage culture festival", d: "Mathura is revered as Lord Krishna's birthplace and Vrindavan as the land of his childhood. The twin towns are full of temples, from the ancient Krishna Janmabhoomi to Vrindavan's Banke Bihari and the modern Prem Mandir, and come alive at Holi and Janmashtami.", a: [["Krishna Janmabhoomi", "Temple complex at Krishna's birthplace"], ["Banke Bihari Temple", "Vrindavan's most beloved temple"], ["Prem Mandir", "White marble temple lit up at night"], ["ISKCON Vrindavan", "Krishna Balaram Mandir"], ["Vishram Ghat", "Riverside ghat with evening aarti"], ["Govardhan Hill", "Pilgrims walk the 21 km parikrama"]], ac: ["Temple circuit", "Holi celebrations (Lathmar Holi in Barsana)", "Yamuna aarti", "Parikrama walk"], f: ["Mathura peda", "Kachori and jalebi", "Lassi"], bt: ["October to March", "Holi (February/March) and Janmashtami (August/September) are spectacular but very crowded."], r: ["Agra Airport (AGR), about 60 km; Delhi (DEL), about 180 km", "Mathura Junction", "About 1 hour from Agra"], days: "1", tip: "Banke Bihari temple has short darshan windows; check timings and expect crowds.", b: "Pilgrims, festival lovers" },
  { s: "lucknow", n: "Lucknow", p: "uttar-pradesh", ll: [26.85, 80.95], t: "heritage city food culture", d: "Lucknow, the city of Nawabs, is known for its refined manners, chikankari embroidery and some of India's finest kebabs. The Bara Imambara's maze, the Rumi Darwaza and the ruins of the 1857 Residency tell its history.", a: [["Bara Imambara and Bhool Bhulaiya", "Vaulted hall and labyrinth"], ["Rumi Darwaza", "Sixty-foot ceremonial gateway"], ["Chota Imambara", "Ornate congregational hall"], ["British Residency", "Ruins from the 1857 siege"], ["Hazratganj", "Colonial-era shopping street"]], ac: ["Kebab and food walk", "Chikankari shopping", "Heritage walk in the old city", "Ambedkar Park at night"], f: ["Galouti kebab", "Awadhi biryani", "Makhan malai (winter)", "Basket chaat"], bt: ["October to March", "Cool winters and festival season."], r: ["Chaudhary Charan Singh International Airport (LKO)", "Lucknow Charbagh station", "Expressways to Agra and Delhi"], days: "1–2", tip: "Eat kebabs in Aminabad or Chowk in the evening, when the old city's food stalls are busiest.", b: "Food lovers, history and culture" },
  { s: "ayodhya", n: "Ayodhya", p: "uttar-pradesh", ll: [26.80, 82.20], t: "pilgrimage heritage", d: "Ayodhya, on the banks of the Sarayu, is revered as the birthplace of Lord Rama. The Shri Ram Janmabhoomi temple, consecrated in 2024, now draws pilgrims from across India, alongside older shrines like Hanuman Garhi and the evening aarti on the ghats.", a: [["Shri Ram Janmabhoomi Mandir", "The new Rama temple"], ["Hanuman Garhi", "Hilltop Hanuman temple"], ["Kanak Bhawan", "Temple of Sita and Rama"], ["Ram ki Paidi", "Ghats on the Sarayu with evening aarti"], ["Guptar Ghat", "Riverside ghat and park"]], ac: ["Temple darshan", "Sarayu aarti", "Deepotsav at Diwali"], f: ["Prasad", "Kachori and sweets", "North Indian thali"], bt: ["October to March", "Diwali's Deepotsav lights the ghats with lakhs of lamps."], r: ["Maharishi Valmiki International Airport (AYJ)", "Ayodhya Dham Junction", "About 2.5 hours from Lucknow"], days: "1", tip: "Phones and bags are not allowed inside the Ram Mandir; use the free lockers.", b: "Pilgrims, families" },
  // Himachal Pradesh
  { s: "shimla", n: "Shimla", p: "himachal-pradesh", ll: [31.10, 77.17], t: "hill snow honeymoon family heritage", d: "Shimla was the summer capital of British India, and its Mall Road, Christ Church and Viceregal Lodge still feel colonial. Pine and deodar forests surround the ridge, and nearby Kufri and Narkanda have winter snow.", a: [["The Ridge and Mall Road", "Pedestrian heart of the town"], ["Christ Church", "Neo-Gothic church from the 1850s"], ["Viceregal Lodge (Rashtrapati Niwas)", "Former Viceroy's residence"], ["Jakhoo Temple", "Hilltop Hanuman temple with a giant statue"], ["Kufri", "Snow point and adventure park"], ["Kalka–Shimla Railway", "UNESCO-listed toy train"]], ac: ["Toy train ride", "Mall Road walk", "Snow activities in Kufri (winter)", "Day trip to Chail or Narkanda"], f: ["Himachali dham", "Siddu", "Hot chai and momos on the Mall"], bt: ["March to June; December to February for snow", "Pleasant summers; snowfall usually from late December."], r: ["Shimla Airport (SLV) has limited flights; Chandigarh (IXC), about 115 km", "Shimla station on the Kalka–Shimla line", "About 3.5 hours from Chandigarh"], days: "2", tip: "Ride the toy train one way and drive the other, to see both the tunnels and the valley views.", b: "Families, honeymooners, first trips to the hills" },
  { s: "manali", n: "Manali", p: "himachal-pradesh", ll: [32.24, 77.19], t: "hill snow adventure honeymoon mountain", d: "Manali sits at the head of the Kullu Valley, with apple orchards, old wooden temples and snow peaks all around. Solang Valley is the adventure hub, and the Atal Tunnel now links Manali to the Lahaul valley beyond the Rohtang Pass.", a: [["Hadimba Temple", "Wooden temple in a cedar forest"], ["Old Manali", "Cafés and village lanes"], ["Solang Valley", "Paragliding, ropeway and snow sports"], ["Atal Tunnel and Sissu", "Tunnel to Lahaul and waterfalls beyond"], ["Rohtang Pass", "High pass with snow (permit required, seasonal)"], ["Vashisht hot springs", "Natural hot springs and temple"]], ac: ["Paragliding", "River rafting in Kullu", "Snow activities", "Café hopping", "Trek to Jogini Falls"], f: ["Siddu", "Trout fish", "Himachali dham"], bt: ["March to June; December to February for snow", "Summer for sightseeing and adventure; winter for snow."], r: ["Kullu–Manali Airport (Bhuntar, KUU), about 50 km, with limited flights; Chandigarh (IXC), about 300 km", "Jogindernagar is the nearest narrow-gauge station; Chandigarh is the practical railhead", "About 12 hours by overnight Volvo bus from Delhi"], days: "3", tip: "Rohtang needs an online permit and is closed on Tuesdays; Sissu via the Atal Tunnel is an easy alternative.", b: "Honeymooners, friends, adventure lovers" },
  { s: "dharamshala", n: "Dharamshala & McLeod Ganj", p: "himachal-pradesh", ll: [32.22, 76.32], t: "hill culture adventure", d: "Dharamshala and the upper town of McLeod Ganj are home to the Dalai Lama and the Tibetan government-in-exile. Monasteries, momos and prayer flags meet British-era churches and the Dhauladhar range, and the Triund trek starts right above town.", a: [["Tsuglagkhang Complex", "The Dalai Lama's temple and residence"], ["Triund trek", "Ridge trek with Dhauladhar views"], ["Bhagsu Waterfall", "Waterfall and temple"], ["St John in the Wilderness", "Church in the cedar forest"], ["HPCA Cricket Stadium", "Mountain-backed cricket ground"], ["Norbulingka Institute", "Tibetan arts and crafts"]], ac: ["Trekking", "Tibetan cooking class", "Meditation", "Café hopping"], f: ["Momos and thukpa", "Tingmo", "Butter tea"], bt: ["March to June and September to November", "Clear views; the monsoon is very wet here."], r: ["Kangra Airport (Gaggal, DHM), about 15 km", "Pathankot, about 85 km", "About 10 hours from Delhi by road"], days: "2–3", tip: "Start the Triund trek early to reach the ridge before the afternoon clouds.", b: "Culture, trekkers, slow travellers" },
  { s: "dalhousie", n: "Dalhousie & Khajjiar", p: "himachal-pradesh", ll: [32.54, 75.98], t: "hill nature honeymoon family", d: "Dalhousie is a quiet colonial hill station spread over five hills, with churches, pine walks and views of the Pir Panjal. Nearby Khajjiar is a meadow ringed by deodar forest that is often called the mini Switzerland of India.", a: [["Khajjiar Meadow", "Meadow with a small lake and forest"], ["St John's Church", "Oldest church in Dalhousie"], ["Panchpula", "Waterfall and streams"], ["Dainkund Peak", "Highest point with valley views"], ["Kalatop Wildlife Sanctuary", "Forest walks"]], ac: ["Horse riding in Khajjiar", "Forest walks", "Zorbing and paragliding", "Day trip to Chamba"], f: ["Chamba chukh (chilli sauce)", "Madra", "Rajma chawal"], bt: ["March to June; December to February for snow", "Pleasant summers; heavy monsoon rain."], r: ["Kangra Airport (DHM), about 130 km; Pathankot airport, about 80 km", "Pathankot station, about 80 km", "About 2.5 hours from Pathankot"], days: "2", tip: "Stay in Khajjiar for a night if you want the meadow without day-trip crowds.", b: "Couples, families" },
  { s: "spiti-valley", n: "Spiti Valley", p: "himachal-pradesh", ll: [32.25, 78.03], t: "mountain adventure desert culture", d: "Spiti is a cold desert valley between India and Tibet, at well over 3,500 metres, with thousand-year-old monasteries, fossil villages and some of the highest inhabited villages in the world. It is a road trip destination for those who don't mind long, rough drives.", a: [["Key Monastery", "Hilltop monastery above Kaza"], ["Chandratal Lake", "Crescent-shaped high-altitude lake"], ["Tabo Monastery", "Founded in 996 CE, with ancient murals"], ["Dhankar Monastery", "Clifftop monastery and lake"], ["Langza and Komic", "High villages with fossils and views"], ["Pin Valley National Park", "Snow leopard habitat"]], ac: ["Road trip", "Monastery visits", "Stargazing", "Homestays", "Short high-altitude walks"], f: ["Thukpa", "Tsampa", "Butter tea"], bt: ["June to September", "The Kunzum Pass road from Manali usually opens around June; the Kinnaur route is open longer."], r: ["Kullu–Manali Airport (KUU) or Shimla; most travellers fly to Chandigarh", "No railway; Shimla or Chandigarh are the railheads", "About 10–12 hours from Manali to Kaza in good conditions"], days: "6–8", tip: "Go in via Kinnaur and out via Manali so you gain altitude gradually.", b: "Road-trippers, photographers, experienced travellers" },
  { s: "kasol", n: "Kasol & Parvati Valley", p: "himachal-pradesh", ll: [32.01, 77.31], t: "hill adventure nature", d: "Kasol is a riverside village in the Parvati Valley known for its cafés, pine forests and treks to Kheerganga, Tosh and Malana. Nearby Manikaran has hot springs and a gurudwara with a community kitchen.", a: [["Parvati River walks", "Riverside paths through pines"], ["Manikaran Sahib", "Gurudwara and hot springs"], ["Kheerganga trek", "Trek to hot springs at the top"], ["Tosh village", "Village at the head of the valley"], ["Chalal", "Short walk across the river"]], ac: ["Trekking", "Camping", "Café hopping", "Hot spring bath"], f: ["Israeli and Himachali café food", "Trout", "Langar at Manikaran"], bt: ["March to June and September to November", "Comfortable trekking weather."], r: ["Kullu–Manali Airport (KUU), about 30 km", "Chandigarh or Jogindernagar railheads", "About 2 hours from Kullu"], days: "2–3", tip: "Kheerganga is a full day each way for most people; plan an overnight at the top.", b: "Backpackers, trekkers, friends" },
  // Uttarakhand
  { s: "rishikesh", n: "Rishikesh", p: "uttarakhand", ll: [30.09, 78.27], t: "pilgrimage adventure wellness", d: "Rishikesh, where the Ganga leaves the Himalaya, is the yoga capital of the world and the place the Beatles came to study meditation. The Laxman Jhula and Ram Jhula footbridges, riverside ashrams and Grade III–IV rapids give it a mix of spirituality and adventure.", a: [["Triveni Ghat", "Evening Ganga aarti"], ["Parmarth Niketan", "Ashram with a famous riverside aarti"], ["Beatles Ashram", "Ruins of Maharishi's ashram with murals"], ["Ram Jhula and Laxman Jhula", "Suspension bridges over the Ganga"], ["Neer Garh Waterfall", "Short hike to falls"], ["Kunjapuri Temple", "Sunrise over the Himalaya"]], ac: ["White-water rafting", "Yoga and meditation classes", "Bungee jumping", "Riverside camping", "Ganga aarti"], f: ["Chhole bhature at Chotiwala", "Ayurvedic café food", "Aloo puri"], bt: ["September to November and February to May", "Rafting season runs roughly from September to June."], r: ["Dehradun (Jolly Grant) Airport (DED), about 20 km", "Yog Nagari Rishikesh station, or Haridwar Junction, about 25 km", "About 6 hours from Delhi by road"], days: "2", tip: "Book rafting with a licensed operator and choose the 16 km stretch from Shivpuri for first-timers.", b: "Adventure, yoga and spiritual travellers" },
  { s: "haridwar", n: "Haridwar", p: "uttarakhand", ll: [29.95, 78.16], t: "pilgrimage", d: "Haridwar is one of Hinduism's seven holiest cities and the place where the Ganga enters the plains. The evening aarti at Har Ki Pauri, with hundreds of lamps floated on the river, is one of India's most moving rituals, and the city hosts the Kumbh Mela every twelve years.", a: [["Har Ki Pauri", "Ghat of the evening Ganga aarti"], ["Mansa Devi Temple", "Hilltop temple reached by ropeway"], ["Chandi Devi Temple", "Temple on Neel Parvat"], ["Bharat Mata Mandir", "Eight-storey temple to Mother India"], ["Rajaji National Park", "Elephant and leopard habitat nearby"]], ac: ["Ganga aarti", "Holy dip", "Ropeway to temples", "Jungle safari at Rajaji"], f: ["Kachori and aloo", "Lassi", "Puri sabzi"], bt: ["October to March", "Cool and clear; Kumbh and Kanwar seasons are very crowded."], r: ["Dehradun (Jolly Grant) Airport (DED), about 35 km", "Haridwar Junction", "About 5 hours from Delhi"], days: "1", tip: "Reach Har Ki Pauri at least an hour before aarti to get a good spot on the ghat.", b: "Pilgrims, families" },
  { s: "nainital", n: "Nainital", p: "uttarakhand", ll: [29.38, 79.46], t: "hill lake honeymoon family", d: "Nainital is a lake town in the Kumaon hills, built around the pear-shaped Naini Lake and the Mall Road. Boating, cable cars and nearby lakes at Bhimtal, Sattal and Naukuchiatal make it a family favourite.", a: [["Naini Lake", "Boating and the Mall Road"], ["Naina Devi Temple", "Lakeside Shakti shrine"], ["Snow View Point", "Cable car to Himalayan views"], ["Tiffin Top", "Viewpoint reached on foot or horseback"], ["Bhimtal and Sattal", "Quieter lakes nearby"], ["Mukteshwar", "Orchards and Himalayan views, 50 km away"]], ac: ["Boating", "Cable car", "Lake-hopping day", "Shopping on the Mall"], f: ["Bal mithai", "Kumaoni bhatt ki churkani", "Momos"], bt: ["March to June and September to November", "Summers are busy; winter can bring light snow."], r: ["Pantnagar Airport (PGH), about 65 km", "Kathgodam station, about 35 km", "About 7 hours from Delhi"], days: "2", tip: "Stay at Bhimtal or Sattal if you prefer quiet; Nainital is a short drive away.", b: "Families, couples" },
  { s: "mussoorie", n: "Mussoorie", p: "uttarakhand", ll: [30.46, 78.07], t: "hill honeymoon family", d: "Mussoorie, the queen of the hills, sits on a ridge above Dehradun with views of the Doon Valley on one side and Himalayan peaks on the other. Landour, its quieter upper cantonment, is known for its bakeries and writers.", a: [["Mall Road and Library Chowk", "Promenade and shopping"], ["Gun Hill", "Ropeway to a viewpoint"], ["Landour and Char Dukan", "Quiet cantonment and cafés"], ["Kempty Falls", "Waterfall 15 km away"], ["Lal Tibba", "Highest point with telescopes"], ["George Everest's House", "Ruins of the surveyor's home"]], ac: ["Ridge walks", "Ropeway", "Café hopping in Landour", "Day trip to Dhanaulti"], f: ["Bun omelette at Char Dukan", "Pancakes", "Garhwali food"], bt: ["March to June and September to November", "Clear autumn views; winter brings occasional snow."], r: ["Dehradun (Jolly Grant) Airport (DED), about 60 km", "Dehradun station, about 35 km", "About 1 hour from Dehradun"], days: "2", tip: "Walk the Landour loop early in the morning for Himalayan views before the haze.", b: "Couples, families, writers' retreats" },
  { s: "jim-corbett", n: "Jim Corbett National Park", p: "uttarakhand", ll: [29.53, 78.77], t: "wildlife nature family", d: "Jim Corbett is India's oldest national park, established in 1936, and the first under Project Tiger. Its sal forests, grasslands and the Ramganga river support tigers, elephants, leopards and over 600 bird species.", a: [["Dhikala zone", "Grasslands and the best tiger territory (overnight permits)"], ["Bijrani zone", "Popular day-safari zone"], ["Jhirna zone", "Open year-round"], ["Garjia Devi Temple", "Temple on a river rock"], ["Corbett Museum", "Jim Corbett's former home"]], ac: ["Jeep safari", "Canter safari", "Birdwatching", "River walks"], f: ["Resort buffets", "Kumaoni dishes"], bt: ["November to June", "Dhikala and most zones close in the monsoon; Jhirna stays open."], r: ["Pantnagar Airport (PGH), about 110 km", "Ramnagar station", "About 6 hours from Delhi"], days: "2", tip: "Dhikala forest lodge stays must be booked on the official portal the moment bookings open.", b: "Wildlife lovers, families, birders" },
  { s: "auli", n: "Auli", p: "uttarakhand", ll: [30.53, 79.57], t: "snow mountain adventure", d: "Auli is a ski resort on the slopes above Joshimath, with views of Nanda Devi, India's second-highest peak. In winter it hosts skiing courses; in summer the meadows are good for walks.", a: [["Auli ropeway", "One of Asia's longest cable cars (check operating status)"], ["Auli ski slopes", "Ski courses in winter"], ["Gorson Bugyal", "Alpine meadow walk"], ["Artificial lake", "High-altitude reservoir"], ["Joshimath", "Gateway town and monastery"]], ac: ["Skiing", "Snow walks", "Meadow trekking", "Photography"], f: ["Garhwali food", "Maggi at the slopes"], bt: ["December to March for snow; April to June for meadows", "Skiing depends on snowfall."], r: ["Dehradun (Jolly Grant) Airport (DED), about 280 km", "Rishikesh, about 260 km", "About 10 hours from Rishikesh"], days: "2–3", tip: "Joshimath has seen land subsidence; we check road and ropeway status before confirming.", b: "Snow lovers, skiers" },
  { s: "kedarnath", n: "Kedarnath", p: "uttarakhand", ll: [30.73, 79.07], t: "pilgrimage mountain trek", d: "Kedarnath is one of the twelve jyotirlingas and part of the Char Dham pilgrimage, set beneath snow peaks at about 3,580 metres. Pilgrims trek around 16 km from Gaurikund or take a helicopter, and the temple opens only from spring to autumn.", a: [["Kedarnath Temple", "Ancient stone Shiva temple"], ["Bhairavnath Temple", "Guardian deity above the temple"], ["Adi Shankaracharya Samadhi", "Memorial behind the temple"], ["Vasuki Tal", "High lake reached by a difficult trek"], ["Gaurikund", "Base village with hot springs"]], ac: ["Trek to the temple", "Helicopter darshan", "Evening aarti"], f: ["Simple vegetarian meals", "Prasad"], bt: ["May to June and September to October", "The temple opens around Akshaya Tritiya (April/May) and closes after Diwali; avoid the monsoon."], r: ["Dehradun (Jolly Grant) Airport (DED), about 240 km to Gaurikund", "Rishikesh, about 215 km", "Road to Gaurikund, then a 16 km trek"], days: "2–3", tip: "Registration with the state government is mandatory; helicopter seats are sold only on the official IRCTC portal.", b: "Pilgrims, trekkers" },
  { s: "badrinath", n: "Badrinath", p: "uttarakhand", ll: [30.74, 79.49], t: "pilgrimage mountain", d: "Badrinath is one of the four Char Dham shrines and a temple to Vishnu, set between the Nar and Narayan peaks on the Alaknanda river at about 3,100 metres. Unlike Kedarnath, it is reachable by road.", a: [["Badrinath Temple", "Colourful Vishnu temple"], ["Tapt Kund", "Hot springs below the temple"], ["Mana Village", "Last village before the Tibet border"], ["Vasudhara Falls", "Waterfall trek from Mana"], ["Bheem Pul", "Natural rock bridge"]], ac: ["Temple darshan", "Hot spring bath", "Walk to Mana", "Short trek to Vasudhara"], f: ["Vegetarian meals", "Prasad"], bt: ["May to June and September to October", "The temple opens around late April or May and closes in November."], r: ["Dehradun (Jolly Grant) Airport (DED), about 315 km", "Rishikesh, about 295 km", "About 10–11 hours from Rishikesh"], days: "2", tip: "Spend a night at Joshimath or Pipalkoti on the way up to break the long drive.", b: "Pilgrims, families" },
  // Punjab
  { s: "amritsar", n: "Amritsar", p: "punjab", ll: [31.63, 74.87], t: "pilgrimage heritage food culture", d: "Amritsar is home to the Harmandir Sahib, the Golden Temple, the holiest shrine of Sikhism, where a free community kitchen serves tens of thousands of meals a day. Jallianwala Bagh and the Attari–Wagah border ceremony are short trips from the temple.", a: [["Golden Temple (Harmandir Sahib)", "Gilded shrine in the Amrit Sarovar"], ["Langar hall", "Free community kitchen"], ["Jallianwala Bagh", "Memorial to the 1919 massacre"], ["Attari–Wagah border", "Evening flag-lowering ceremony"], ["Partition Museum", "Stories of the 1947 partition"], ["Gobindgarh Fort", "Restored fort with shows"]], ac: ["Golden Temple at night", "Volunteer at the langar", "Border ceremony", "Food walk"], f: ["Amritsari kulcha", "Amritsari fish", "Lassi", "Sarson da saag and makki di roti"], bt: ["October to March", "Pleasant days; foggy nights in December and January."], r: ["Sri Guru Ram Dass Jee International Airport (ATQ)", "Amritsar Junction", "About 8 hours from Delhi by road"], days: "1–2", tip: "Visit the Golden Temple both early morning and late evening; the night view is magical.", b: "Pilgrims, food lovers, families" },
  // Jammu & Kashmir
  { s: "srinagar", n: "Srinagar", p: "jammu-and-kashmir", ll: [34.08, 74.80], t: "lake honeymoon heritage family", d: "Srinagar is Kashmir's summer capital, known for Dal Lake's houseboats and shikaras, Mughal gardens laid out by emperors, and floating vegetable markets at dawn. Tulips bloom at Asia's largest tulip garden in spring.", a: [["Dal Lake shikara ride", "Gondola ride past houseboats and markets"], ["Nishat and Shalimar Bagh", "Terraced Mughal gardens"], ["Indira Gandhi Memorial Tulip Garden", "Tulips in late March–April"], ["Shankaracharya Temple", "Hilltop temple over the city"], ["Hazratbal Shrine", "White marble shrine on the lake"], ["Floating vegetable market", "Early-morning market on boats"]], ac: ["Houseboat stay", "Shikara ride", "Mughal gardens tour", "Shopping for pashmina and papier-mâché"], f: ["Wazwan feast", "Rogan josh", "Kahwa", "Noon chai with girda bread"], bt: ["March to October", "Tulips in spring, lush summers and golden chinars in autumn."], r: ["Sheikh ul-Alam International Airport (SXR), about 15 km", "Srinagar station (connected by the Udhampur–Srinagar–Baramulla line)", "About 8–10 hours from Jammu by road"], days: "2–3", tip: "Spend one night on a houseboat and the rest in a hotel; it gives you both experiences.", b: "Honeymooners, families" },
  { s: "gulmarg", n: "Gulmarg", p: "jammu-and-kashmir", ll: [34.05, 74.38], t: "snow mountain adventure honeymoon", d: "Gulmarg, the meadow of flowers, is a high resort at about 2,650 metres. In winter it is one of Asia's best ski areas; in summer the meadows bloom. The two-stage Gulmarg Gondola climbs to Kongdori and Apharwat.", a: [["Gulmarg Gondola", "Cable car to Kongdori and Apharwat"], ["Gulmarg meadows", "Golf course and pony rides"], ["St Mary's Church", "Stone church from 1902"], ["Khilanmarg", "Meadow walk with views of Nanga Parbat"], ["Strawberry Valley", "Short drive out of town"]], ac: ["Skiing and snowboarding", "Gondola ride", "Pony ride", "Snow activities"], f: ["Kashmiri kahwa", "Wazwan dishes"], bt: ["December to March for snow; May to September for meadows", "Snow sports in winter; flowers in summer."], r: ["Srinagar Airport (SXR), about 55 km", "Srinagar or Baramulla stations", "About 1.5–2 hours from Srinagar"], days: "1–2", tip: "Book gondola tickets online the day before; they sell out quickly in peak season.", b: "Snow lovers, honeymooners, skiers" },
  { s: "pahalgam", n: "Pahalgam", p: "jammu-and-kashmir", ll: [34.02, 75.32], t: "hill nature honeymoon family", d: "Pahalgam sits where the Lidder river runs through pine forest, and it is the base for the Amarnath Yatra. Meadows at Baisaran, Aru and Betaab Valley make easy day trips by pony or taxi.", a: [["Betaab Valley", "Green valley named after a film"], ["Aru Valley", "Meadows and trek base"], ["Chandanwari", "Start of the Amarnath trek"], ["Baisaran", "Pony ride to a forest meadow"], ["Lidder riverside", "Picnics and trout fishing"]], ac: ["Pony rides", "Riverside walks", "Trout fishing", "Rafting (seasonal)"], f: ["Trout fish", "Kashmiri pulao", "Kahwa"], bt: ["April to October", "Summer meadows; snow in winter."], r: ["Srinagar Airport (SXR), about 95 km", "Anantnag station, about 45 km", "About 2.5 hours from Srinagar"], days: "2", tip: "Local union taxis are required for Aru, Betaab and Chandanwari; we include them in your quote.", b: "Families, honeymooners" },
  { s: "sonamarg", n: "Sonamarg", p: "jammu-and-kashmir", ll: [34.30, 75.29], t: "mountain snow nature", d: "Sonamarg, the meadow of gold, lies on the road to Ladakh beside the Sindh river, with the Thajiwas Glacier a short pony ride away. It is the last big stop before the Zoji La pass.", a: [["Thajiwas Glacier", "Pony ride or walk to snowfields"], ["Sindh river", "Rafting and riverside walks"], ["Zoji La viewpoint", "High pass on the way to Ladakh (seasonal)"], ["Zero Point", "Snow beyond Zoji La"], ["Vishansar Lake trek", "Start of the Great Lakes trek"]], ac: ["Pony ride to glacier", "Snow activities", "Rafting", "Trekking"], f: ["Kashmiri kahwa", "Simple dhaba meals"], bt: ["April to October", "Snow remains near the glacier into summer."], r: ["Srinagar Airport (SXR), about 80 km", "Srinagar station", "About 2.5 hours from Srinagar"], days: "1", tip: "The Z-Morh tunnel now keeps Sonamarg open longer, but Zoji La still closes in heavy snow.", b: "Families, road-trippers" },
  { s: "katra", n: "Katra (Vaishno Devi)", p: "jammu-and-kashmir", ll: [32.99, 74.93], t: "pilgrimage", d: "Katra is the base for the Mata Vaishno Devi shrine, one of the most visited pilgrimage sites in India, set in a cave about 12 km up the Trikuta hills. Pilgrims walk, ride ponies, use battery cars or take a helicopter part of the way.", a: [["Mata Vaishno Devi Bhawan", "Holy cave shrine"], ["Bhairon Nath Temple", "Visited after darshan, reached by ropeway"], ["Ardhkuwari", "Halfway cave shrine"], ["Banganga", "Start of the trek"], ["Jammu's Raghunath Temple", "Temple complex in Jammu city"]], ac: ["Pilgrim trek", "Helicopter to Sanjichhat", "Ropeway to Bhairon", "Night darshan"], f: ["Rajma chawal", "Kalari cheese", "Prasad"], bt: ["March to October", "Navratri is the busiest time; winters are cold but the shrine stays open."], r: ["Jammu Airport (IXJ), about 50 km", "Shri Mata Vaishno Devi Katra station", "About 1.5 hours from Jammu"], days: "2", tip: "Register for the yatra (RFID card) before starting; helicopter seats must be booked on the official shrine board site.", b: "Pilgrims, families" },
  // Ladakh
  { s: "leh", n: "Leh", p: "ladakh", ll: [34.16, 77.58], t: "mountain culture adventure", d: "Leh, at about 3,500 metres, is Ladakh's capital and the base for exploring the region. The nine-storey Leh Palace, Shanti Stupa and monasteries at Thiksey, Hemis and Shey are within an easy drive.", a: [["Leh Palace", "Seventeenth-century royal palace"], ["Shanti Stupa", "White stupa with sunset views"], ["Thiksey Monastery", "Monastery resembling the Potala Palace"], ["Hemis Monastery", "Largest monastery, with a summer festival"], ["Magnetic Hill", "Optical illusion on the Srinagar road"], ["Hall of Fame", "Army museum"]], ac: ["Monastery tour", "Rafting on the Indus and Zanskar", "Leh market walk", "Sindhu Darshan"], f: ["Thukpa", "Skyu", "Butter tea", "Apricot jam"], bt: ["May to September", "Summer is the season; Hemis festival is in June or July."], r: ["Kushok Bakula Rimpochee Airport (IXL)", "No railway; nearest railhead is Jammu Tawi", "Via Manali (about 475 km) or Srinagar (about 420 km), both seasonal"], days: "3", tip: "Rest completely on arrival day; altitude sickness is common if you rush.", b: "Adventure and culture travellers" },
  { s: "nubra-valley", n: "Nubra Valley", p: "ladakh", ll: [34.57, 77.56], t: "desert mountain adventure", d: "Nubra Valley lies beyond the Khardung La pass, a high desert where the Shyok and Nubra rivers meet. Sand dunes at Hunder, double-humped Bactrian camels and the Diskit monastery's giant Maitreya Buddha are the highlights.", a: [["Khardung La", "One of the world's highest motorable passes"], ["Hunder sand dunes", "Bactrian camel rides"], ["Diskit Monastery", "Giant Maitreya Buddha statue"], ["Turtuk", "Balti village near the border"], ["Panamik hot springs", "Natural springs"]], ac: ["Camel ride", "Desert camping", "Village walk in Turtuk"], f: ["Balti dishes", "Apricot juice"], bt: ["June to September", "Khardung La is open in summer and can close after snow."], r: ["Leh Airport (IXL), about 120 km", "No railway", "About 5 hours from Leh over Khardung La"], days: "1–2", tip: "An Inner Line Permit is needed for Nubra; carry several printed copies.", b: "Adventure lovers, families" },
  { s: "pangong-lake", n: "Pangong Lake", p: "ladakh", ll: [33.75, 78.66], t: "lake mountain adventure", d: "Pangong Tso is a long, high-altitude lake at about 4,250 metres, stretching from Ladakh into Tibet. Its water shifts from turquoise to deep blue with the light, and camps along the shore offer stays beside it.", a: [["Pangong lakeshore", "Changing colours of the lake"], ["Chang La", "High pass on the way"], ["Spangmik and Merak", "Lakeside villages with camps"], ["Lukung", "First viewpoint on arrival"]], ac: ["Lakeside camping", "Photography", "Stargazing"], f: ["Camp meals", "Maggi and tea at Chang La"], bt: ["June to September", "Partly frozen in winter; summer is the main season."], r: ["Leh Airport (IXL), about 225 km", "No railway", "About 5–6 hours from Leh via Chang La"], days: "1", tip: "Nights at Pangong are freezing even in summer; camps provide heaters or electric blankets at a cost.", b: "Photographers, adventure lovers" },
  // Madhya Pradesh
  { s: "khajuraho", n: "Khajuraho", p: "madhya-pradesh", ll: [24.85, 79.93], t: "heritage culture", d: "Khajuraho's Chandela-dynasty temples, built around 950 to 1050 CE, are famous for their exquisite carvings of gods, celestial dancers and everyday life, including the erotic sculptures. About two dozen survive in a UNESCO-listed group.", a: [["Western Group of Temples", "Kandariya Mahadeva and Lakshmana temples"], ["Eastern Group (Jain temples)", "Parsvanath and Adinath temples"], ["Light-and-sound show", "Evening show at the Western Group"], ["Panna National Park", "Tiger reserve 30 km away"], ["Raneh Falls", "Canyon of coloured granite"]], ac: ["Guided temple tour", "Khajuraho Dance Festival (February)", "Panna safari", "Cycling between temple groups"], f: ["Bundelkhandi meals", "Poha jalebi"], bt: ["October to March", "Pleasant days; the dance festival is held in February."], r: ["Khajuraho Airport (HJR)", "Khajuraho railway station", "About 4 hours from Orchha"], days: "1–2", tip: "Hire an approved guide; the carvings tell stories you will miss on your own.", b: "Art and history lovers" },
  { s: "ujjain", n: "Ujjain", p: "madhya-pradesh", ll: [23.18, 75.78], t: "pilgrimage heritage", d: "Ujjain is one of the seven sacred cities of Hinduism and home to the Mahakaleshwar Jyotirlinga, famous for its pre-dawn Bhasma Aarti. The city on the Shipra river hosts the Simhastha Kumbh every twelve years.", a: [["Mahakaleshwar Temple", "Jyotirlinga with the Bhasma Aarti"], ["Mahakal Lok corridor", "New temple corridor with sculptures"], ["Ram Ghat", "Evening aarti on the Shipra"], ["Kal Bhairav Temple", "Unusual temple tradition"], ["Jantar Mantar (Vedh Shala)", "Eighteenth-century observatory"], ["Omkareshwar", "Island jyotirlinga, about 140 km away"]], ac: ["Bhasma Aarti", "Temple circuit", "Shipra aarti", "Day trip to Omkareshwar"], f: ["Poha", "Dal bafla", "Indori street food (nearby)"], bt: ["October to March", "Comfortable for temple visits."], r: ["Indore Airport (IDR), about 55 km", "Ujjain Junction", "About 1.5 hours from Indore"], days: "1–2", tip: "Bhasma Aarti bookings open online in advance and fill fast; there is a strict dress code.", b: "Pilgrims, families" },
  { s: "bhopal", n: "Bhopal & Sanchi", p: "madhya-pradesh", ll: [23.26, 77.41], t: "heritage lake city", d: "Bhopal is the city of lakes and the capital of Madhya Pradesh. It is the base for the Great Stupa at Sanchi (UNESCO) and the prehistoric rock shelters of Bhimbetka, two of India's most important ancient sites.", a: [["Sanchi Stupa", "Buddhist stupa from the 3rd century BCE, 45 km away"], ["Bhimbetka rock shelters", "Prehistoric paintings, 45 km away"], ["Upper Lake (Bhojtal)", "Boating and sunsets"], ["Taj-ul-Masajid", "One of India's largest mosques"], ["Tribal Museum", "Excellent modern museum"], ["Bhojpur Temple", "Giant unfinished Shiva temple"]], ac: ["Day trip to Sanchi", "Bhimbetka visit", "Lake boating", "Museum visits"], f: ["Bhopali biryani", "Poha", "Sulaimani chai"], bt: ["October to March", "Pleasant winter days."], r: ["Raja Bhoj Airport (BHO)", "Bhopal Junction and Rani Kamlapati stations", "Well connected to Indore and Jabalpur"], days: "2", tip: "The Tribal Museum is one of the best in India; give it at least two hours.", b: "History and museum lovers" },
  { s: "kanha", n: "Kanha National Park", p: "madhya-pradesh", ll: [22.33, 80.61], t: "wildlife nature family", d: "Kanha's sal forests and meadows inspired Kipling's Jungle Book. It is one of India's best-managed tiger reserves and the home of the hard-ground barasingha, a deer saved from extinction here.", a: [["Kanha zone", "Open meadows with good sightings"], ["Kisli and Mukki zones", "Forest safari zones"], ["Bamni Dadar", "Sunset point"], ["Kanha Museum", "Interpretation centre"], ["Barasingha meadows", "Swamp deer herds"]], ac: ["Jeep safari", "Birdwatching", "Nature walks in the buffer zone", "Tribal village visit"], f: ["Lodge meals", "Local Gond dishes"], bt: ["October to June", "Closed in the monsoon; spring and summer offer the best sightings."], r: ["Jabalpur Airport (JLR), about 165 km", "Jabalpur or Gondia stations", "About 4 hours from Jabalpur"], days: "2–3", tip: "Combine Kanha with Bandhavgarh; they are about five hours apart.", b: "Wildlife lovers, photographers" },
  { s: "bandhavgarh", n: "Bandhavgarh National Park", p: "madhya-pradesh", ll: [23.72, 81.02], t: "wildlife nature", d: "Bandhavgarh has one of the highest densities of tigers in India, in a landscape of rocky hills, sal forest and an ancient hilltop fort. Its Tala zone is famous for sightings.", a: [["Tala zone", "Core zone with frequent tiger sightings"], ["Magadhi and Khitauli zones", "Other core zones"], ["Bandhavgarh Fort", "Hilltop ruins inside the park"], ["Shesh Shaiya", "Reclining Vishnu statue"], ["Buffer zone safaris", "Night and day safaris outside the core"]], ac: ["Tiger safari", "Photography", "Birdwatching"], f: ["Lodge meals"], bt: ["October to June", "Closed in the monsoon; March–May is peak for sightings."], r: ["Jabalpur Airport (JLR), about 200 km", "Umaria or Katni stations", "About 4.5 hours from Jabalpur"], days: "2–3", tip: "Book safaris on the MP Forest portal as early as possible; Tala zone fills first.", b: "Wildlife lovers, photographers" },
  { s: "pachmarhi", n: "Pachmarhi", p: "madhya-pradesh", ll: [22.47, 78.43], t: "hill nature family adventure", d: "Pachmarhi is Madhya Pradesh's only hill station, on a plateau in the Satpura range with waterfalls, cave paintings and forest trails. It sits within the Satpura Tiger Reserve.", a: [["Bee Falls", "Waterfall with a natural pool"], ["Jata Shankar caves", "Cave shrine with a stream"], ["Pandav Caves", "Five rock-cut caves"], ["Dhoopgarh", "Highest point in central India, for sunset"], ["Apsara Vihar", "Pool and falls for families"]], ac: ["Waterfall walks", "Jeep safari in Satpura", "Cave visits", "Sunset at Dhoopgarh"], f: ["Local MP dishes", "Bhutte ka kees"], bt: ["October to June", "Pleasant most of the year; waterfalls flow best after the monsoon."], r: ["Bhopal (BHO), about 200 km", "Pipariya station, about 50 km", "About 5 hours from Bhopal"], days: "2", tip: "Hire a registered gypsy from the town office; private vehicles cannot enter most sights.", b: "Families, nature lovers" },
  { s: "orchha", n: "Orchha", p: "madhya-pradesh", ll: [25.35, 78.64], t: "heritage culture", d: "Orchha is a small medieval town on the Betwa river, with Bundela palaces, temples and riverside chhatris that are hauntingly quiet compared to Rajasthan. Its Ram Raja Temple is unique in worshipping Rama as a king.", a: [["Jahangir Mahal", "Palace built for the Mughal emperor's visit"], ["Raja Mahal", "Palace with murals"], ["Ram Raja Temple", "Rama worshipped as king"], ["Chaturbhuj Temple", "Towering temple with views"], ["Royal Chhatris", "Cenotaphs on the Betwa"]], ac: ["Palace tour", "Sunset at the chhatris", "River rafting on the Betwa", "Light-and-sound show"], f: ["Bundelkhandi thali"], bt: ["October to March", "Comfortable winter days."], r: ["Gwalior (GWL), about 120 km", "Jhansi Junction, about 16 km", "About 20 minutes from Jhansi"], days: "1", tip: "Arrive on the Gatimaan or Shatabdi to Jhansi and add Orchha on the way to Khajuraho.", b: "Heritage lovers, photographers" },
  // West Bengal
  { s: "kolkata", n: "Kolkata", p: "west-bengal", ll: [22.57, 88.36], t: "city heritage culture food", d: "Kolkata was the capital of British India until 1911 and remains India's cultural capital: home to Tagore, Satyajit Ray and Mother Teresa, the Victoria Memorial and the Howrah Bridge. Its sweets, street food and Durga Puja are legendary.", a: [["Victoria Memorial", "White marble museum and gardens"], ["Howrah Bridge", "Iconic cantilever bridge"], ["Dakshineswar Kali Temple", "Riverside temple"], ["Mother House", "Mother Teresa's tomb"], ["Kumartuli", "Potters who make Durga idols"], ["Indian Museum", "Oldest museum in India"]], ac: ["Heritage tram ride", "Ganga ferry", "Food walk", "College Street book market", "Durga Puja pandal hopping"], f: ["Rosogolla and mishti doi", "Kathi roll", "Kosha mangsho", "Puchka"], bt: ["October to March", "Durga Puja (September/October) is the highlight."], r: ["Netaji Subhas Chandra Bose International Airport (CCU)", "Howrah and Sealdah stations", "National highways to Odisha and north Bengal"], days: "2", tip: "Take the ferry across the Hooghly to see Howrah Bridge from the water.", b: "Culture, food and history lovers" },
  { s: "darjeeling", n: "Darjeeling", p: "west-bengal", ll: [27.04, 88.26], t: "hill nature honeymoon family", d: "Darjeeling, the queen of the hills, is famous for its tea and for sunrise views of Kanchenjunga from Tiger Hill. The UNESCO-listed Darjeeling Himalayan Railway still runs its little steam and diesel trains through town.", a: [["Tiger Hill", "Sunrise over Kanchenjunga"], ["Darjeeling Himalayan Railway", "Joy ride to Ghum and the Batasia Loop"], ["Happy Valley Tea Estate", "Tea factory and tasting"], ["Himalayan Mountaineering Institute", "Museum of Everest expeditions"], ["Padmaja Naidu Zoo", "Red pandas and snow leopards"], ["Peace Pagoda", "Japanese Buddhist stupa"]], ac: ["Tea tasting", "Toy train joy ride", "Mall Road walk", "Ropeway", "Monastery visits"], f: ["Momos", "Thukpa", "First-flush Darjeeling tea"], bt: ["March to May and October to December", "Clearest views in autumn; spring is flower season."], r: ["Bagdogra Airport (IXB), about 70 km", "New Jalpaiguri (NJP), about 75 km", "About 3 hours from Bagdogra"], days: "2–3", tip: "Leave for Tiger Hill around 4 am; clear mornings are most likely in October–November.", b: "Families, honeymooners, tea lovers" },
  { s: "sundarbans", n: "Sundarbans", p: "west-bengal", ll: [21.94, 88.89], t: "wildlife nature", d: "The Sundarbans is the largest mangrove forest in the world, spread across the Ganges delta into Bangladesh. Boat safaris through its creeks look for the Royal Bengal tiger, saltwater crocodiles and kingfishers.", a: [["Sajnekhali Watch Tower", "Watchtower and interpretation centre"], ["Sudhanyakhali", "Watchtower with frequent sightings"], ["Dobanki canopy walk", "Raised walkway in the forest"], ["Netidhopani", "Ruins of an old temple"], ["Village life", "Island villages and honey collectors"]], ac: ["Boat safari", "Birdwatching", "Village walk", "Folk performances"], f: ["Bengali fish curry", "Crab dishes", "Lodge meals"], bt: ["October to March", "Cool and calm; summer is hot and humid."], r: ["Kolkata Airport (CCU), about 110 km to Godkhali", "Canning station, about 30 km", "About 3 hours from Kolkata to the jetty"], days: "2", tip: "Tiger sightings are rare; the real reward is the silence of the creeks and the birdlife.", b: "Nature lovers, birders" },
  { s: "kalimpong", n: "Kalimpong", p: "west-bengal", ll: [27.06, 88.47], t: "hill nature culture", d: "Kalimpong is a quieter hill town than Darjeeling, known for its nurseries, monasteries and views over the Teesta valley. It is a good base for the Lava–Lolegaon forests and the old Silk Route villages.", a: [["Deolo Hill", "Viewpoint and park"], ["Zang Dhok Palri Monastery", "Monastery consecrated by the Dalai Lama"], ["Morgan House", "Colonial-era bungalow"], ["Flower nurseries", "Cactus and orchid nurseries"], ["Lava and Lolegaon", "Forest villages nearby"]], ac: ["Nursery visits", "Monastery walk", "Day trip to Lava", "Paragliding at Deolo"], f: ["Kalimpong cheese and lollipops", "Momos"], bt: ["March to May and October to December", "Clear autumn skies."], r: ["Bagdogra Airport (IXB), about 75 km", "New Jalpaiguri (NJP), about 70 km", "About 3 hours from Bagdogra"], days: "1–2", tip: "Combine with Darjeeling and Gangtok; Kalimpong sits neatly between them.", b: "Slow travellers, nature lovers" },
  // Odisha
  { s: "puri", n: "Puri", p: "odisha", ll: [19.81, 85.83], t: "pilgrimage beach", d: "Puri is one of the Char Dham pilgrimages and home to the Jagannath Temple, famous for its annual Rath Yatra. It also has a long beach on the Bay of Bengal, where sand artists work on the shore.", a: [["Jagannath Temple", "Twelfth-century temple (Hindus only)"], ["Puri Beach", "Long beach and sand art"], ["Gundicha Temple", "Destination of the Rath Yatra"], ["Raghurajpur", "Heritage crafts village of pattachitra painters"], ["Chilika Lake (Satapada)", "Dolphin-spotting boat rides"]], ac: ["Rath Yatra (June/July)", "Pattachitra workshop", "Beach sunrise", "Temple visit"], f: ["Mahaprasad", "Khaja", "Chhena poda", "Odia fish curry"], bt: ["October to March", "Pleasant beach weather; the Rath Yatra is in June or July."], r: ["Biju Patnaik International Airport, Bhubaneswar (BBI), about 60 km", "Puri station", "About 1.5 hours from Bhubaneswar"], days: "1–2", tip: "Visit Raghurajpur village to see pattachitra paintings made by families of artists.", b: "Pilgrims, families, beach lovers" },
  { s: "bhubaneswar", n: "Bhubaneswar", p: "odisha", ll: [20.30, 85.82], t: "heritage pilgrimage city", d: "Bhubaneswar, the temple city of India, once had more than 700 temples around the Bindu Sagar lake. The Lingaraj and Mukteswar temples are masterpieces of Kalinga architecture, and the Jain caves at Udayagiri and Khandagiri date to the 2nd century BCE.", a: [["Lingaraj Temple", "Eleventh-century Shiva temple (Hindus only inside)"], ["Mukteswar Temple", "The gem of Odisha architecture"], ["Udayagiri and Khandagiri Caves", "Ancient Jain rock-cut caves"], ["Dhauli", "Ashokan rock edicts and Peace Pagoda"], ["Odisha State Museum", "Palm-leaf manuscripts and art"], ["Ekamra Haat", "Handloom and craft market"]], ac: ["Temple walk", "Cave visit", "Handloom shopping", "Dhauli light-and-sound show"], f: ["Dalma", "Pakhala", "Rasabali"], bt: ["October to March", "Comfortable weather; the Ekamra festival is in winter."], r: ["Biju Patnaik International Airport (BBI)", "Bhubaneswar station", "Highways to Puri and Konark"], days: "1–2", tip: "Combine with Puri and Konark for Odisha's golden triangle in three days.", b: "Heritage and architecture lovers" },
  { s: "konark", n: "Konark", p: "odisha", ll: [19.89, 86.09], t: "heritage beach", d: "Konark's thirteenth-century Sun Temple was built as a giant stone chariot for Surya, with twenty-four carved wheels and seven horses. It is a UNESCO site and one of the great monuments of India.", a: [["Konark Sun Temple", "Stone chariot of the Sun God"], ["Konark Archaeological Museum", "Sculptures from the temple"], ["Chandrabhaga Beach", "Beach a few kilometres away"], ["Ramachandi Temple", "Temple where a river meets the sea"]], ac: ["Guided temple tour", "Konark Dance Festival (December)", "Beach visit"], f: ["Odia seafood", "Chhena poda"], bt: ["October to March", "Pleasant; the dance festival is held in early December."], r: ["Biju Patnaik International Airport (BBI), about 65 km", "Puri station, about 35 km", "About 1 hour from Puri on the marine drive"], days: "1", tip: "Drive the coast road from Puri to Konark; it passes the Ramachandi beach.", b: "History buffs, photographers" },
  { s: "chilika", n: "Chilika Lake", p: "odisha", ll: [19.72, 85.32], t: "nature wildlife lake", d: "Chilika is Asia's largest brackish-water lagoon, separated from the Bay of Bengal by a sandbar. In winter it hosts huge flocks of migratory birds, especially at Nalabana, and the Satapada mouth is home to Irrawaddy dolphins.", a: [["Nalabana Bird Sanctuary", "Migratory birds in winter"], ["Satapada dolphin point", "Irrawaddy dolphins"], ["Kalijai Temple", "Island temple"], ["Rajhans Island", "Sandbar beach"], ["Mangalajodi", "Community-run birding wetland"]], ac: ["Boat safari", "Birdwatching", "Dolphin spotting", "Island beach visit"], f: ["Chilika crab and prawns"], bt: ["November to February", "Peak bird season."], r: ["Biju Patnaik International Airport (BBI), about 100 km", "Balugaon station", "About 2 hours from Bhubaneswar"], days: "1", tip: "Mangalajodi at dawn is one of India's best birding experiences.", b: "Birders, nature lovers" },
  // Bihar
  { s: "bodh-gaya", n: "Bodh Gaya", p: "bihar", ll: [24.70, 84.99], t: "pilgrimage heritage", d: "Bodh Gaya is where Siddhartha Gautama attained enlightenment under the Bodhi tree and became the Buddha. The Mahabodhi Temple is a UNESCO site, and monasteries built by Buddhist countries line the town's streets.", a: [["Mahabodhi Temple", "Temple at the site of enlightenment"], ["Bodhi Tree", "Descendant of the original tree"], ["Great Buddha Statue", "80-foot statue"], ["International monasteries", "Thai, Japanese, Bhutanese and other temples"], ["Dungeshwari Caves", "Where the Buddha practised austerities"]], ac: ["Meditation", "Monastery walk", "Evening chanting at Mahabodhi"], f: ["Tilkut (winter)", "Litti chokha", "Tibetan food"], bt: ["October to March", "Peak pilgrim season with pleasant days."], r: ["Gaya Airport (GAY), about 12 km", "Gaya Junction, about 15 km", "About 4 hours from Patna"], days: "1–2", tip: "Visit Mahabodhi at dawn when monks gather for chanting under the Bodhi tree.", b: "Pilgrims, spiritual travellers" },
  { s: "nalanda-rajgir", n: "Nalanda & Rajgir", p: "bihar", ll: [25.03, 85.42], t: "heritage pilgrimage", d: "Nalanda was one of the world's first residential universities, flourishing from the 5th to 12th centuries; its excavated ruins are a UNESCO site. Nearby Rajgir, ringed by hills, was where the Buddha often preached, at Vulture's Peak.", a: [["Nalanda Mahavihara ruins", "Remains of the ancient university"], ["Nalanda Archaeological Museum", "Finds from the site"], ["Vulture's Peak (Griddhakuta)", "Where the Buddha preached"], ["Vishwa Shanti Stupa, Rajgir", "Peace pagoda reached by ropeway"], ["Rajgir hot springs", "Sacred hot water springs"], ["Rajgir glass bridge", "Skywalk in the nature safari park"]], ac: ["Guided ruins walk", "Ropeway ride", "Buddhist circuit"], f: ["Litti chokha", "Khaja from Silao"], bt: ["October to March", "Pleasant days for walking the ruins."], r: ["Gaya Airport (GAY), about 80 km", "Rajgir station", "About 2.5 hours from Bodh Gaya"], days: "1", tip: "Do Nalanda in the morning and Rajgir in the afternoon; they are 15 km apart.", b: "History lovers, pilgrims" },
  // Sikkim
  { s: "gangtok", n: "Gangtok", p: "sikkim", ll: [27.33, 88.61], t: "hill mountain snow lake culture", d: "Gangtok is Sikkim's clean, lively capital on a ridge facing Kanchenjunga. MG Marg is car-free, monasteries like Rumtek sit on the surrounding hills, and day trips go up to Tsomgo Lake and the Nathula Pass on the China border.", a: [["MG Marg", "Car-free promenade"], ["Tsomgo (Changu) Lake", "Glacial lake at about 3,750 m (permit)"], ["Nathula Pass", "Border pass (permit; closed Mon–Tue)"], ["Rumtek Monastery", "Seat of the Karmapa lineage"], ["Enchey Monastery", "Small monastery above town"], ["Banjhakri Falls", "Park and waterfall"]], ac: ["Monastery visits", "Ropeway", "Day trip to Tsomgo and Nathula", "Shopping on MG Marg"], f: ["Momos", "Thukpa", "Sha phaley", "Gundruk soup"], bt: ["March to May and October to December", "Clear views in autumn; spring flowers."], r: ["Pakyong Airport (PYG), about 35 km (limited flights); Bagdogra (IXB), about 125 km", "New Jalpaiguri (NJP), about 120 km", "About 4–5 hours from Bagdogra"], days: "3", tip: "Carry ID photos and copies; permits for Tsomgo and Nathula are issued a day ahead.", b: "Families, honeymooners" },
  { s: "pelling", n: "Pelling", p: "sikkim", ll: [27.30, 88.24], t: "mountain culture nature", d: "Pelling sits on a ridge in West Sikkim facing Kanchenjunga at close range. Pemayangtse Monastery, the ruins of the old capital at Rabdentse and a glass skywalk are nearby.", a: [["Kanchenjunga views", "Sunrise from the ridge"], ["Pemayangtse Monastery", "One of Sikkim's oldest monasteries"], ["Rabdentse Ruins", "Second capital of the Sikkim kingdom"], ["Pelling Skywalk", "Glass walkway and Chenrezig statue"], ["Khecheopalri Lake", "Sacred wish-fulfilling lake"], ["Kanchenjunga Falls", "Waterfall nearby"]], ac: ["Sunrise viewing", "Monastery visits", "Short treks", "Lake walk"], f: ["Momos", "Churpi"], bt: ["March to May and October to December", "Clear autumn mornings."], r: ["Bagdogra (IXB), about 145 km", "New Jalpaiguri (NJP), about 140 km", "About 4 hours from Gangtok"], days: "1–2", tip: "Get a room facing the mountain; the sunrise view is the reason to stay.", b: "Families, nature lovers" },
  { s: "lachung", n: "Lachung & Yumthang", p: "sikkim", ll: [27.69, 88.74], t: "mountain snow nature", d: "Lachung is a village in North Sikkim at about 2,700 metres and the base for Yumthang, the valley of flowers, and Zero Point beyond it. Rhododendrons bloom in spring and snow covers the valley in winter.", a: [["Yumthang Valley", "Rhododendron valley with hot springs"], ["Zero Point (Yumesamdong)", "Snowfields at about 4,700 m"], ["Lachung Monastery", "Village monastery"], ["Bhim Nala Falls", "Waterfall on the road"], ["Gurudongmar Lake", "Sacred high lake (via Lachen)"]], ac: ["Snow play at Zero Point", "Valley walks", "Hot spring visit"], f: ["Simple homestay meals", "Thukpa"], bt: ["March to June and October to December", "Rhododendrons in April–May; snow in winter."], r: ["Bagdogra (IXB), about 245 km", "New Jalpaiguri (NJP)", "About 6 hours from Gangtok"], days: "2", tip: "North Sikkim needs a Protected Area Permit and a registered local vehicle; we arrange both.", b: "Snow lovers, families" },
  // Meghalaya
  { s: "shillong", n: "Shillong", p: "meghalaya", ll: [25.58, 91.89], t: "hill nature culture", d: "Shillong is Meghalaya's hill capital, a lively town of pine forests, colonial bungalows and a famous rock music culture. Umiam Lake, Elephant Falls and the viewpoint at Shillong Peak are close by.", a: [["Umiam Lake", "Large reservoir with water sports"], ["Elephant Falls", "Three-tier waterfall"], ["Shillong Peak", "Highest point with city views"], ["Don Bosco Museum", "Excellent museum of northeastern cultures"], ["Ward's Lake", "Garden lake in town"], ["Police Bazaar", "Shopping and street food"]], ac: ["Lake activities", "Museum visit", "Café and music scene", "Golf at one of Asia's oldest courses"], f: ["Jadoh", "Dohneiiong", "Tungrymbai"], bt: ["October to April", "Clear and cool; the cherry blossom festival is in November."], r: ["Shillong Airport (Umroi, SHL), about 30 km; Guwahati (GAU), about 120 km", "Guwahati station, about 100 km", "About 3 hours from Guwahati"], days: "2", tip: "Allow extra time for traffic in Shillong town; plan sightseeing outside peak hours.", b: "Families, nature and music lovers" },
  { s: "cherrapunji", n: "Cherrapunji (Sohra)", p: "meghalaya", ll: [25.27, 91.73], t: "nature adventure", d: "Sohra, better known as Cherrapunji, is one of the wettest places on earth and has the waterfalls and deep gorges to prove it. Its living root bridges, grown from rubber fig roots by Khasi villagers, are the region's most famous sight.", a: [["Double-decker root bridge, Nongriat", "Two-level living root bridge"], ["Nohkalikai Falls", "One of India's tallest plunge waterfalls"], ["Seven Sisters Falls", "Seasonal falls on a cliff"], ["Mawsmai Cave", "Limestone cave"], ["Arwah Cave", "Cave with fossils"], ["Dainthlen Falls", "Waterfall with a legend"]], ac: ["Root bridge trek", "Cave exploration", "Waterfall viewpoints", "Canyoning (with operators)"], f: ["Jadoh", "Smoked pork", "Khasi rice dishes"], bt: ["October to April", "Dry for trekking; the monsoon makes waterfalls roar."], r: ["Shillong Airport (SHL), about 70 km; Guwahati (GAU), about 150 km", "Guwahati station", "About 1.5 hours from Shillong"], days: "1–2", tip: "Stay overnight at Nongriat if you want the root bridge without the day crowds.", b: "Trekkers, nature lovers" },
  { s: "dawki", n: "Dawki & Mawlynnong", p: "meghalaya", ll: [25.18, 92.02], t: "nature lake culture", d: "Dawki is a border town on the Umngot River, whose water is so clear in winter that boats appear to hover above the riverbed. Nearby Mawlynnong is known as one of Asia's cleanest villages, with a living root bridge of its own.", a: [["Umngot River boat ride", "Crystal-clear river in the dry season"], ["Shnongpdeng", "Riverside camping and snorkelling"], ["Mawlynnong village", "Tidy Khasi village with a sky view tower"], ["Riwai living root bridge", "Single-decker root bridge"], ["India–Bangladesh border at Dawki", "Border crossing viewpoint"]], ac: ["Boating", "Camping", "Village walk", "Cliff jumping and kayaking"], f: ["Khasi meals", "Fresh river fish"], bt: ["November to April", "The river is clearest in winter; murky in the monsoon."], r: ["Shillong Airport (SHL), about 110 km", "Guwahati station", "About 2.5 hours from Shillong"], days: "1", tip: "Go between December and March for the clearest water.", b: "Photographers, families" },
  // Assam
  { s: "kaziranga", n: "Kaziranga National Park", p: "assam", ll: [26.58, 93.17], t: "wildlife nature", d: "Kaziranga is a UNESCO-listed park on the Brahmaputra floodplain and home to about two-thirds of the world's greater one-horned rhinos. Elephants, wild buffalo, swamp deer and tigers share its tall grasslands.", a: [["Central (Kohora) range", "Most popular safari range"], ["Western (Bagori) range", "Good rhino sightings"], ["Eastern (Agaratoli) range", "Birding and quieter safaris"], ["Elephant safari", "Early morning ride through the grass"], ["Orchid and Biodiversity Park", "Local orchids and culture"]], ac: ["Jeep safari", "Elephant safari", "Tea estate visit", "Birdwatching"], f: ["Assamese thali", "Duck curry", "Assam tea"], bt: ["November to April", "The park is closed in the monsoon (roughly May to October)."], r: ["Jorhat (JRH), about 95 km; Guwahati (GAU), about 220 km", "Furkating or Jakhalabandha stations", "About 4.5–5 hours from Guwahati"], days: "2", tip: "Book the earliest jeep safari; mist rising off the grasslands at dawn is the best time for rhinos.", b: "Wildlife lovers, families" },
  { s: "guwahati", n: "Guwahati", p: "assam", ll: [26.14, 91.74], t: "pilgrimage city nature", d: "Guwahati is the gateway to the Northeast, spread along the Brahmaputra. The Kamakhya Temple on Nilachal Hill is one of the most important Shakti shrines, and river cruises at sunset show the city at its best.", a: [["Kamakhya Temple", "Major Shakti peetha on Nilachal Hill"], ["Umananda Island", "River island temple"], ["Brahmaputra sunset cruise", "Evening cruise on the river"], ["Assam State Museum", "Regional history and art"], ["Pobitora Wildlife Sanctuary", "Rhinos about 50 km away"]], ac: ["River cruise", "Temple visit", "Silk shopping (muga and pat)", "Pobitora safari"], f: ["Assamese fish tenga", "Pitha", "Masor tenga"], bt: ["October to April", "Comfortable; Ambubachi Mela (June) draws huge crowds to Kamakhya."], r: ["Lokpriya Gopinath Bordoloi International Airport (GAU)", "Guwahati station", "Highways to Shillong and Kaziranga"], days: "1", tip: "Use Guwahati as a one-night stop between Shillong and Kaziranga.", b: "Pilgrims, transit stops" },
  { s: "majuli", n: "Majuli", p: "assam", ll: [26.95, 94.17], t: "culture nature", d: "Majuli is one of the largest river islands in the world, in the middle of the Brahmaputra. It is the centre of Assamese neo-Vaishnavite culture, with satras (monasteries) that preserve dance, mask-making and music traditions.", a: [["Kamalabari and Auniati satras", "Vaishnavite monasteries"], ["Samaguri satra", "Traditional mask-making"], ["Mishing villages", "Stilt houses and weaving"], ["Brahmaputra ferry", "River crossing from Jorhat"], ["Birdwatching wetlands", "Migratory birds in winter"]], ac: ["Satra visits", "Cycling", "Mask-making workshop", "Village homestay"], f: ["Mishing rice beer (apong)", "Assamese fish dishes"], bt: ["October to March", "Dry season; the Raas Mahotsav is in November."], r: ["Jorhat Airport (JRH), about 40 km plus ferry", "Jorhat station", "Ferry from Nimati Ghat, then road"], days: "1–2", tip: "Ferry timings vary with the river; start early from Jorhat.", b: "Culture lovers, slow travellers" },
  // Arunachal Pradesh
  { s: "tawang", n: "Tawang", p: "arunachal-pradesh", ll: [27.59, 91.86], t: "mountain culture snow lake", d: "Tawang, at about 3,000 metres near the Bhutan and Tibet borders, is home to India's largest monastery, founded in the seventeenth century. The road crosses the Sela Pass and high lakes surround the town.", a: [["Tawang Monastery", "Largest monastery in India"], ["Sela Pass and lake", "High pass at about 4,170 m"], ["Madhuri (Sangetsar) Lake", "Lake formed by an earthquake"], ["Tawang War Memorial", "1962 war memorial"], ["Jaswant Garh", "War memorial on the Sela road"], ["Nuranang Falls", "Tall waterfall near Jang"]], ac: ["Monastery visit", "High lake trips", "Torgya festival (January)", "Snow play"], f: ["Thukpa", "Zan", "Butter tea"], bt: ["March to June and September to November", "Snow from December can close Sela Pass."], r: ["Tezpur Airport (TEZ), about 320 km; Guwahati (GAU), about 450 km", "Tezpur or Guwahati stations", "Two days by road from Guwahati, with a night at Dirang or Bomdila"], days: "3", tip: "Bum La Pass and Sangetsar Lake need separate army permits arranged locally.", b: "Adventure and culture travellers" },
  { s: "ziro", n: "Ziro Valley", p: "arunachal-pradesh", ll: [27.55, 93.83], t: "culture nature festival", d: "Ziro is a high valley of rice fields and pine hills, home to the Apatani people, whose farming system integrates fish and rice. The Ziro Festival of Music each September draws independent music fans from across India.", a: [["Apatani villages", "Traditional houses and culture"], ["Rice-fish fields", "Unique wet-rice farming"], ["Talley Valley Wildlife Sanctuary", "Forest reserve"], ["Kile Pakho", "Ridge with valley views"], ["Meghna Cave Temple", "Ancient cave shrine"]], ac: ["Village walks", "Ziro Festival of Music", "Birdwatching", "Homestays"], f: ["Apatani bamboo-shoot dishes", "Rice beer"], bt: ["March to October", "September for the music festival; spring for green fields."], r: ["Donyi Polo Airport, Itanagar (HGI), about 115 km", "Naharlagun station, about 100 km", "About 4 hours from Itanagar"], days: "2–3", tip: "Book festival stays very early; homestays are limited.", b: "Culture and music lovers" },
  // Nagaland
  { s: "kohima", n: "Kohima", p: "nagaland", ll: [25.67, 94.11], t: "culture festival hill", d: "Kohima is Nagaland's capital and the site of a pivotal 1944 battle, remembered at the Commonwealth War Cemetery. The Naga Heritage Village at Kisama hosts the Hornbill Festival, and Khonoma, Asia's first green village, is nearby.", a: [["Kohima War Cemetery", "Memorial to the 1944 battle"], ["Kisama Heritage Village", "Site of the Hornbill Festival"], ["Khonoma village", "Green village with terraced fields"], ["Dzukou Valley trek", "Valley of flowers on the Manipur border"], ["Kohima Cathedral", "Large Catholic cathedral"], ["Local market", "Naga produce and crafts"]], ac: ["Hornbill Festival (Dec 1–10)", "Village walks", "Dzukou trek", "Naga cuisine tasting"], f: ["Smoked pork with bamboo shoot", "Axone (fermented soybean)", "Galho"], bt: ["October to May", "Hornbill Festival in early December."], r: ["Dimapur Airport (DMU), about 75 km", "Dimapur station", "About 3 hours from Dimapur"], days: "2–3", tip: "Carry warm layers; December nights at Kisama are cold.", b: "Culture and festival lovers" },
  // Andaman & Nicobar
  { s: "port-blair", n: "Port Blair", p: "andaman-and-nicobar", ll: [11.62, 92.73], t: "island beach heritage", isl: true, ferry: ["havelock", "neil-island"], d: "Port Blair, now officially Sri Vijaya Puram, is the capital of the Andaman and Nicobar Islands and where every trip starts. The Cellular Jail, where freedom fighters were imprisoned, holds a moving light-and-sound show, and Ross Island and North Bay are short boat rides away.", a: [["Cellular Jail", "Colonial prison and national memorial"], ["Ross Island (Netaji Subhas Chandra Bose Dweep)", "Ruins of the British headquarters"], ["North Bay", "Coral and glass-bottom boats"], ["Corbyn's Cove", "City beach"], ["Chidiya Tapu", "Sunset point and bird sanctuary"], ["Anthropological Museum", "Island tribes and culture"]], ac: ["Light-and-sound show", "Glass-bottom boat ride", "Sea walk at North Bay", "Sunset at Chidiya Tapu"], f: ["Fresh seafood", "Coconut prawn curry", "Fish thali"], bt: ["October to May", "Calm seas; the monsoon cancels some boat trips."], r: ["Veer Savarkar International Airport (IXZ)", "No railway; ships run from Chennai, Kolkata and Visakhapatnam", "Not connected by road to the mainland"], days: "1–2", tip: "Book the Cellular Jail show in advance; the English show runs in the evening.", b: "Families, history lovers" },
  { s: "havelock", n: "Havelock Island (Swaraj Dweep)", p: "andaman-and-nicobar", ll: [12.00, 92.98], t: "island beach adventure honeymoon", isl: true, ferry: ["port-blair", "neil-island"], d: "Havelock, renamed Swaraj Dweep, is the Andamans' best-known island, with Radhanagar Beach often ranked among Asia's finest. It is the main base for scuba diving and snorkelling in India.", a: [["Radhanagar Beach", "Long white-sand beach with forest behind"], ["Elephant Beach", "Snorkelling and water sports by boat"], ["Kalapathar Beach", "Black rocks and turquoise water"], ["Dive sites", "Coral reefs for beginners and certified divers"], ["Vijaynagar Beach", "Quiet beach for sunrise"]], ac: ["Scuba diving", "Snorkelling", "Kayaking in mangroves", "Sea walk", "Sunset at Radhanagar"], f: ["Grilled fish", "Seafood curries", "Beach café food"], bt: ["October to May", "Best visibility for diving from November to April."], r: ["Veer Savarkar Airport (IXZ), then ferry", "No railway", "Private ferries take about 1.5–2.5 hours from Port Blair"], days: "2–3", tip: "Do a try-dive on your first full day; if you love it you have time for a second dive.", b: "Honeymooners, divers, beach lovers" },
  { s: "neil-island", n: "Neil Island (Shaheed Dweep)", p: "andaman-and-nicobar", ll: [11.83, 93.03], t: "island beach honeymoon", isl: true, ferry: ["port-blair", "havelock"], d: "Neil Island, renamed Shaheed Dweep, is a small, laid-back island of farms, coral beaches and a natural rock bridge. Most visitors cycle around it in a day.", a: [["Natural Bridge (Howrah Bridge)", "Rock arch at low tide"], ["Bharatpur Beach", "Calm water for snorkelling"], ["Laxmanpur Beach", "Sunset beach"], ["Sitapur Beach", "Sunrise beach"], ["Coral reefs", "Glass-bottom boat rides"]], ac: ["Cycling", "Snorkelling", "Glass-bottom boat", "Sunset viewing"], f: ["Fresh seafood", "Coconut water"], bt: ["October to May", "Low tide is the time to see the natural bridge."], r: ["Veer Savarkar Airport (IXZ), then ferry", "No railway", "Ferries take about 1–2 hours from Port Blair or Havelock"], days: "1", tip: "Check tide timings for the Natural Bridge; it is only walkable at low tide.", b: "Couples, slow travellers" },
  // Lakshadweep
  { s: "agatti", n: "Agatti", p: "lakshadweep", ll: [10.86, 72.19], t: "island beach adventure", isl: true, d: "Agatti is the only Lakshadweep island with an airport, a narrow strip of coconut palms with a wide, clear lagoon on one side. It is the gateway to the other islands and a good base for snorkelling and diving.", a: [["Agatti lagoon", "Shallow, clear lagoon"], ["Coral reefs", "Snorkelling and diving sites"], ["Kalpitti Island", "Uninhabited islet nearby"], ["Agatti beach", "Long sandy beach"]], ac: ["Snorkelling", "Scuba diving", "Kayaking", "Glass-bottom boat ride"], f: ["Tuna dishes", "Coconut-based curries"], bt: ["October to May", "Calm seas; rough during the monsoon."], r: ["Agatti Airport (AGX), flights from Kochi", "No railway", "Ships from Kochi take about 14–18 hours"], days: "2–3", tip: "Permits are mandatory and take time; apply at least a month ahead.", b: "Divers, adventurous couples" },
  { s: "bangaram", n: "Bangaram", p: "lakshadweep", ll: [10.94, 72.29], t: "island beach honeymoon", isl: true, d: "Bangaram is a small, uninhabited teardrop-shaped island surrounded by a lagoon, reached by boat from Agatti. It is the closest thing India has to a desert-island stay, with limited accommodation and excellent snorkelling.", a: [["Bangaram lagoon", "Turquoise lagoon around the island"], ["Tinnakara and Parali islands", "Nearby islets"], ["House reef", "Snorkelling off the beach"], ["Sunset beach", "Quiet evening walks"]], ac: ["Snorkelling", "Kayaking", "Island hopping", "Doing nothing at all"], f: ["Resort meals", "Fresh fish"], bt: ["October to May", "Calm and sunny; check resort operating status."], r: ["Agatti Airport (AGX), then about 1.5 hours by boat", "No railway", "Boat transfer from Agatti"], days: "2–3", tip: "Accommodation is very limited and operated under the administration's rules; we confirm availability before quoting.", b: "Honeymooners, nature lovers" },
];
